// Situational jokes, not a stream of distractions. Delivered only at state changes.
const cast={
 morrow:{idle:['I have no eyelids. This is a terrible matchup for you.','My hobbies include standing here and noticing things.','I cancelled my plans. They were also standing here.'],notice:['A fascinating ceiling you have on your phone.','That was a glance. I have filed it.'],warning:['Your thumb has requested another recess. Denied.','I can see you. It is literally my only qualification.'],rage:['PUT IT DOWN. I AM BECOMING A PRINTER.','THIS MEETING COULD HAVE BEEN YOU WORKING.'],calm:['Excellent. Back to being furniture.','I saw nothing. Continue making that true.'],win:['You finished. I will be insufferable about this.','Good work. That compliment was a limited edition.'],pie:['I do not have a mouth. Explain the catering.','Cream in my cooling vents. Very professional.'],water:['I am not dishwasher safe. We discussed this.','My warranty just left the chat.'],leave:['CLASS PAUSED. Your escape has been added to the minutes.'],select:['I have all day. You do not.']},
 riot:{idle:['I warmed up by arguing with the loading screen.','You bring the homework. I bring unnecessary intensity.','My anger management class asked for a transfer.'],notice:['That better be a very educational thumb.','You again? We JUST made eye contact.'],warning:['Do not make me square up to a notification.','I have beef with your entire screen-time report.'],rage:['PHONE DOWN. I DID NOT STRETCH FOR NOTHING.','YOUR HOMEWORK IS NOT INSIDE MY FACE.'],calm:['Good. Saved by the look-away.','Fine. I will fight the air instead.'],win:['You did it. Annoyingly impressive.','Respect. Temporary, but respect.'],pie:['WHO PUT A BAKERY IN THE ARMOURY?','I trained for punches. Not patisserie.'],water:['I AM STEAMING. NOW LITERALLY.','Great. Now I am angry AND squeaky.'],leave:['CLASS PAUSED. Nice escape. Terrible stealth.'],select:['Pick me. Make poor decisions efficiently.']},
 rhea:{idle:['I believe in you. Your notifications, less so.','Your future self asked me to supervise.'],notice:['Just checking the time? Suspiciously often.'],warning:['Your to-do list would like a word.'],rage:['YOUR TASK. NOT MY FACE.'],calm:['There you go. Keep that energy.'],win:['Finished. That is a good look on you.'],pie:['A bold use of your education.'],water:['Hydration was not the assignment.'],leave:['Class paused. Come back and finish strong.'],select:['One session. Give yourself a chance.']}
};
const gentle={idle:['One small start. That is enough for now.'],notice:['Quick glance? Back to your task when you can.'],warning:['Let’s give your work a little space.'],rage:['Eyes away. One step at a time.'],calm:['That’s it. Keep going.'],leave:['Class paused. Your place is saved.'],win:['You showed up and finished. Well done.']};
export function createDialogue(random=Math.random){const previous=new Map();return (character,event,tone='strict')=>{const savage={rage:['GET OFF THE BLOODY SCREEN. My patience is not a renewable resource.','PUT THE DAMN PHONE DOWN. I am not the assignment.']};const pool=(tone==='gentle'&&gentle[event])||(tone==='savage'&&savage[event])||cast[character]?.[event]||cast.rhea[event]||cast.rhea.idle;const key=character+event+tone,last=previous.get(key);let index=Math.floor(random()*pool.length);if(pool.length>1&&index===last)index=(index+1)%pool.length;previous.set(key,index);return pool[index];};}
